const { buildFact } = require("./lib/fact.js");
const crypto = require("crypto");
// 按契约 §5 的规范化串拼法（唯一一种写法）
function norm(fi) {
  const p = (n,w=2)=>String(n).padStart(w,"0");
  const dt = `${p(fi.y,4)}-${p(fi.m)}-${p(fi.d)} ${p(fi.h)}:${p(fi.mi)}`;
  const place = fi.city ? String(fi.city) : `${Number(fi.lonEast).toFixed(6)},${Number(fi.lat).toFixed(6)}`;
  const gender = fi.gender;
  const cal = fi.basis ? `basis=${fi.basis}` : "";
  return [dt, place, gender, cal].join("|");
}
function plateVersion(fact){ const s = norm(fact.input); return fact.schema + "@" + crypto.createHash("sha256").update(Buffer.from(s,"utf8")).digest("hex").slice(0,12); }
